import{at as e,it as t,n,vt as r}from"./chunks/framework.UwwvkjGo.js";var i=JSON.parse(`{"title":"Brand","description":"","frontmatter":{},"headers":[],"relativePath":"brand/index.md","filePath":"brand/index.md"}`),a={name:`brand/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<div><h1 id="brand" tabindex="-1">Brand <a class="header-anchor" href="#brand" aria-label="Permalink to “Brand”">​</a></h1><p>How JSPrismarine looks and sounds. The docs site implements this page; the tokens below live in <code>tools/docs/site/.vitepress/theme/brand.css</code> and the reusable pieces in <code>theme/components/</code>.</p><h2 id="position" tabindex="-1">Position <a class="header-anchor" href="#position" aria-label="Permalink to “Position”">​</a></h2><p>JSPrismarine is the Bedrock server you run, own and build on. It is a product people choose, not a library index. The brand is flat, bold and direct: big type, solid color blocks, hard edges, and real commands and numbers in place of decoration.</p><p>Four audiences use the site, and every page should make clear which one it serves:</p><table tabindex="0"><thead><tr><th>Audience</th><th>Wants</th><th>Entry point</th></tr></thead><tbody><tr><td>Players</td><td>Join a server and know what works</td><td>Play</td></tr><tr><td>Hosts</td><td>Install, configure and operate it</td><td>Host</td></tr><tr><td>Add-on devs</td><td>Data packs, plugins and the API</td><td>Build</td></tr><tr><td>Contributors</td><td>Clone, change, test and ship</td><td>Contribute</td></tr></tbody></table><h2 id="color" tabindex="-1">Color <a class="header-anchor" href="#color" aria-label="Permalink to “Color”">​</a></h2><p>The accent is <code>#5ca48a</code>, shared with the JSPrismarine website. Every other color supports it.</p><table tabindex="0"><thead><tr><th>Token</th><th>Hex</th><th>Use</th></tr></thead><tbody><tr><td><code>--jsp-accent</code></td><td><code>#5ca48a</code></td><td>Primary accent: buttons, highlights, active states.</td></tr><tr><td><code>--jsp-forest</code></td><td><code>#003829</code></td><td>Dark brand surface and light-mode link color.</td></tr><tr><td><code>--jsp-deep</code></td><td><code>#00281d</code></td><td>Darkest surface, shadows and ground lines.</td></tr><tr><td><code>--jsp-mint</code></td><td><code>#a9d9c6</code></td><td>Body text on forest, light facets.</td></tr><tr><td><code>--jsp-cream</code></td><td><code>#efe9da</code></td><td>Light surface and text on dark.</td></tr><tr><td><code>--jsp-ink</code></td><td><code>#0b1713</code></td><td>Text on light, terminal surface.</td></tr><tr><td><code>--jsp-signal</code></td><td><code>#ff6b3d</code></td><td>Signal orange. Rare: one small spot per view.</td></tr></tbody></table><p>Rules:</p><ul><li>Surfaces are flat. No gradients, glows, blurs or translucent glass.</li><li>Signal orange marks a single thing, such as a prompt, a cursor or the prism&#39;s core. Never use it for large fills of body UI, and never for links.</li><li>Text on <code>--jsp-accent</code> is <code>--jsp-forest</code>. Text on <code>--jsp-signal</code> is <code>--jsp-ink</code>.</li><li>Keep body text at WCAG AA contrast or better against its surface.</li></ul><h2 id="type" tabindex="-1">Type <a class="header-anchor" href="#type" aria-label="Permalink to “Type”">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Family</th><th>Weights</th><th>Notes</th></tr></thead><tbody><tr><td>Display</td><td>Bricolage Grotesque</td><td>500, 800</td><td>Tight tracking (<code>-0.04em</code> and below).</td></tr><tr><td>Mono</td><td>JetBrains Mono</td><td>400, 700</td><td>Commands, labels, logs and code.</td></tr></tbody></table><p>Headlines are set heavy and tight, in sentence case, and are allowed to be very large. Small labels are mono, uppercase and letter-spaced. System fonts are the fallback when the web fonts do not load.</p><h2 id="mark" tabindex="-1">Mark <a class="header-anchor" href="#mark" aria-label="Permalink to “Mark”">​</a></h2><p>The mark is a prism: an isosceles triangle cut into three flat facets (<code>--jsp-accent</code> left, <code>--jsp-mint</code> right, <code>--jsp-forest</code> base) with a small <code>--jsp-signal</code> triangle at its core.</p><ul><li>Use <code>PrismMark</code> from the theme rather than redrawing it.</li><li>Keep clear space of half the mark&#39;s width on every side.</li><li>Do not rotate, outline, add shadows or recolor the facets. On a forest surface, swap the forest base facet for <code>--jsp-deep</code>.</li><li>The wordmark is <code>JSPrismarine</code>, one word, camel case, in Bricolage Grotesque 800.</li></ul><h2 id="shape-and-motion" tabindex="-1">Shape and motion <a class="header-anchor" href="#shape-and-motion" aria-label="Permalink to “Shape and motion”">​</a></h2><ul><li>Corners are rounded to <code>14px</code> on panels and <code>10px</code> on controls. Pills are fully round.</li><li>Primary actions carry a hard offset shadow (<code>4px 4px 0</code>, no blur) that collapses on press.</li><li>Grids are tight: <code>10px</code> gaps between solid blocks.</li><li>Motion is short and mechanical. Honor <code>prefers-reduced-motion</code> by stopping tickers and cursors.</li></ul><h2 id="voice" tabindex="-1">Voice <a class="header-anchor" href="#voice" aria-label="Permalink to “Voice”">​</a></h2><ul><li>State what the thing does. &quot;One binary to host it.&quot; beats &quot;A powerful solution for hosting.&quot;</li><li>Prefer real commands, file names and numbers over adjectives. If a number is a sample, label it.</li><li>Address the reader directly and keep sentences short.</li><li>American English, sentence case headings, no exclamation marks, no emoji.</li></ul><h2 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to “Components”">​</a></h2><p>The docs theme exposes the brand as Vue components registered globally, so any page that allows HTML can use them. Pages staged from <code>docs/</code> render as plain Markdown, so use them from site-owned pages such as <code>tools/docs/site/index.md</code>.</p><table tabindex="0"><thead><tr><th>Component</th><th>Purpose</th></tr></thead><tbody><tr><td><code>PrismMark</code></td><td>The prism logo as inline SVG, any size.</td></tr><tr><td><code>BrandButton</code></td><td>Primary and outline buttons with the hard shadow.</td></tr><tr><td><code>TerminalWindow</code></td><td>A server-console frame. Lines are passed through the slot.</td></tr><tr><td><code>AudienceTabs</code></td><td>Tabs that swap a pitch, a snippet and links per audience.</td></tr><tr><td><code>BentoGrid</code>, <code>BentoTile</code></td><td>Solid color tiles for short claims or data.</td></tr><tr><td><code>ParityBars</code></td><td>Horizontal bars from the parity tracker data.</td></tr><tr><td><code>Ticker</code></td><td>A looping banner of short phrases.</td></tr></tbody></table><h2 id="content-comes-from-the-repository" tabindex="-1">Content comes from the repository <a class="header-anchor" href="#content-comes-from-the-repository" aria-label="Permalink to “Content comes from the repository”">​</a></h2><p>The landing page states no fact that the repository already records. <code>tools/docs/site/project.data.mts</code> reads the version, package list, Node and pnpm requirements, supported protocols and default port at build time, and fails the docs build when a command or package the page shows disappears. The startup preview uses the server&#39;s real log lines, and the parity bars read the tracker snapshot. Add a new claim to the page by adding it to that loader, not by typing the value into a component.</p><h2 id="changing-the-brand" tabindex="-1">Changing the brand <a class="header-anchor" href="#changing-the-brand" aria-label="Permalink to “Changing the brand”">​</a></h2><p>Change a token in <code>brand.css</code>, not a hex value in a component. Update this page in the same commit when a token, font or rule changes.</p></div>`,1)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};